const src = $('Normalize PA Request').first().json;
const raw = String($json.output || '');
const a = raw.indexOf('{');
const b = raw.lastIndexOf('}');
let p = {};
try { p = JSON.parse(raw.slice(a, b + 1)); } catch (e) { p = {}; }
const urgency = String(src.urgency || 'routine').toLowerCase();
const fallbackDays = urgency === 'expedited' ? 1 : 3;
const days = Math.max(1, Math.min(14, parseInt(p.follow_up_days, 10) || fallbackDays));
return [{ json: {
  pa_id: src.pa_id,
  received_at: src.received_at,
  patient_ref: src.patient_ref,
  payer: src.payer,
  procedure_name: src.procedure_name,
  cpt_code: src.cpt_code,
  ordering_provider: src.ordering_provider,
  urgency: urgency,
  submitted_date: src.submitted_date,
  clinical_summary: String(src.clinical_summary || '').slice(0, 2500),
  completeness_score: parseInt(p.completeness_score, 10) || 0,
  missing_docs: Array.isArray(p.missing_docs) ? p.missing_docs.join('; ') : String(p.missing_docs || 'none flagged'),
  risk_note: String(p.risk_note || 'no risk note returned'),
  follow_up_days: days,
  next_follow_up_date: $now.plus({ days: days }).toFormat('yyyy-LL-dd'),
  payer_message: String(p.payer_message || ''),
  requester_email: src.requester_email,
  coordinator_email: src.coordinator_email,
  status: 'submitted',
  last_action: 'logged with AI completeness check'
} }];

const body = $('Payer Response Webhook').first().json.body || {};
const paId = String(body.pa_id || '').trim();
const decision = String(body.decision || 'pending').trim().toLowerCase();
const reason = String(body.reason || 'no reason provided').trim();
const rows = $input.all().map(function (i) { return i.json; });
let hit = null;
for (const r of rows) {
  if (r && String(r.pa_id || '').trim() === paId) { hit = r; }
}
return [{ json: {
  found: !!hit,
  pa_id: paId,
  decision: decision,
  reason: reason,
  decision_date: String(body.decision_date || $now.toISO()),
  patient_ref: hit ? String(hit.patient_ref || '') : '',
  payer: hit ? String(hit.payer || '') : '',
  procedure_name: hit ? String(hit.procedure_name || '') : '',
  cpt_code: hit ? String(hit.cpt_code || '') : '',
  urgency: hit ? String(hit.urgency || '') : '',
  submitted_date: hit ? String(hit.submitted_date || '') : '',
  missing_docs: hit ? String(hit.missing_docs || '') : '',
  requester_email: hit ? String(hit.requester_email || '') : '',
  payer_appeal_email: String(body.payer_appeal_email || ''),
  coordinator_email: 'user@example.com'
} }];

