const src = $('Match Response To Request').first().json;
const raw = String($json.output || '');
const a = raw.indexOf('{');
const b = raw.lastIndexOf('}');
let p = {};
try { p = JSON.parse(raw.slice(a, b + 1)); } catch (e) { p = {}; }
return [{ json: {
  pa_id: src.pa_id,
  payer: src.payer,
  decision: src.decision,
  reason: src.reason,
  decision_date: src.decision_date,
  payer_appeal_email: src.payer_appeal_email,
  coordinator_email: src.coordinator_email,
  requester_email: src.requester_email,
  denial_category: String(p.denial_category || 'denial'),
  appeal_subject: String(p.appeal_subject || ('Appeal for ' + src.pa_id)),
  appeal_body: String(p.appeal_body || 'The appeal draft was not returned. Write the appeal by hand from the denial letter.'),
  attachments: Array.isArray(p.attachments) ? p.attachments.join(', ') : String(p.attachments || 'none listed'),
  peer_to_peer_needed: !!(p.peer_to_peer_needed),
  next_step: String(p.next_step || 'send the appeal and watch the follow up date')
} }];

const today = $now.toFormat('yyyy-LL-dd');
const rows = $input.all().map(function (i) { return i.json; }).filter(function (r) { return r && r.pa_id; });
const due = rows.filter(function (r) {
  const st = String(r.status || '').toLowerCase();
  const dueOn = String(r.next_follow_up_date || '').slice(0, 10);
  return (st === 'submitted' || st === 'pending' || st === 'pended') && dueOn && dueOn <= today;
});
const lines = due.map(function (r) {
  const sent = String(r.submitted_date || '').slice(0, 10);
  let age = 0;
  try { age = Math.max(0, Math.round($now.diff(DateTime.fromISO(sent), 'days').days)); } catch (e) { age = 0; }
  return r.pa_id + ' | ' + r.payer + ' | ' + r.procedure_name + ' (CPT ' + r.cpt_code + ') | status ' + r.status
    + ' | sent to payer ' + sent + ' | ' + age + ' days out | missing: ' + (r.missing_docs || 'none flagged');
});
return [{ json: {
  today: today,
  chase_count: due.length,
  chase_lines: lines.join('\n'),
  expedited_waiting: due.filter(function (r) { return String(r.urgency || '').toLowerCase() === 'expedited'; }).length
} }];

const p = (function () {
  const raw = String($json.output || '');
  const a = raw.indexOf('{');
  const b = raw.lastIndexOf('}');
  try { return JSON.parse(raw.slice(a, b + 1)); } catch (e) { return {}; }
})();
const today = $('Find PA Needing Chase').first().json.today;
const count = $('Find PA Needing Chase').first().json.chase_count;
return [{ json: {
  mail_to: 'user@example.com',
  mail_subject: 'PA chase list for ' + today + ': ' + count + ' request(s) need a nudge',
  mail_body: String(p.digest || 'No digest was returned.') + '\n\nTop action: ' + String(p.top_action || 'Work the oldest request first.'),
  tg_text: 'PA chase list ' + today + ': ' + count + ' request(s) due. ' + String(p.top_action || '')
} }];
